      "style.css": "body {\n  font-family: system-ui, -apple-system, sans-serif;\n  background-color: #090d16;\n  color: #f8fafc;\n  display: flex;\n  justify-content: center;\n  padding: 30px 16px;\n  margin: 0;\n}\n\n.app-container {\n  width: 100%;\n  max-width: 440px;\n  background: #131d2e;\n  padding: 24px;\n  border-radius: 16px;\n  box-shadow: 0 10px 30px rgba(0,0,0,0.4);\n  border: 1px solid #1e293b;\n}\n\nheader h1 {\n  margin: 0;\n  color: #10b981;\n  font-size: 24px;\n}\n\n.tagline {\n  margin: 4px 0 16px;\n  font-size: 12px;\n  color: #94a3b8;\n}\n\nform {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n\ninput {\n  flex: 1;\n  padding: 10px 14px;\n  background: #090d16;\n  border: 1px solid #334155;\n  color: #fff;\n  border-radius: 8px;\n  font-size: 14px;\n  outline: none;\n}\n\ninput:focus {\n  border-color: #10b981;\n}\n\nbutton {\n  background: #10b981;\n  color: #090d16;\n  font-weight: 700;\n  border: none;\n  padding: 10px 16px;\n  border-radius: 8px;\n  cursor: pointer;\n  font-size: 14px;\n  transition: opacity 0.2s;\n}\n\nbutton:hover {\n  opacity: 0.9;\n}\n\n.stats-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 12px;\n  color: #64748b;\n  margin-bottom: 12px;\n  padding-bottom: 8px;\n  border-bottom: 1px solid #1e293b;\n}\n\n#clearAllBtn {\n  background: transparent;\n  color: #ef4444;\n  padding: 0;\n  font-size: 12px;\n}\n\nul {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\nli {\n  background: #090d16;\n  padding: 10px 12px;\n  border-radius: 8px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  border: 1px solid #1e293b;\n}\n\nli.completed span {\n  text-decoration: line-through;\n  color: #64748b;\n}\n\n.task-text {\n  cursor: pointer;\n  flex: 1;\n}\n\n.delete-btn {\n  background: #ef4444;\n  color: white;\n  padding: 4px 8px;\n  border-radius: 6px;\n  font-size: 12px;\n}",
      "script.js": "// 1. Select DOM Elements\nconst form = document.getElementById('todoForm');\nconst input = document.getElementById('taskInput');\nconst taskList = document.getElementById('taskList');\nconst taskCount = document.getElementById('taskCount');\nconst clearAllBtn = document.getElementById('clearAllBtn');\n\n// 2. State & LocalStorage\nlet tasks = JSON.parse(localStorage.getItem('fahmrise_tasks')) || [\n  { id: 1, text: 'Learn JavaScript with FAHMRISE', completed: false }\n];\n\nfunction saveAndRender() {\n  localStorage.setItem('fahmrise_tasks', JSON.stringify(tasks));\n  render();\n}\n\nfunction render() {\n  taskList.innerHTML = '';\n  tasks.forEach((task) => {\n    const li = document.createElement('li');\n    if (task.completed) li.classList.add('completed');\n\n    const span = document.createElement('span');\n    span.className = 'task-text';\n    span.textContent = task.text;\n    span.onclick = () => {\n      task.completed = !task.completed;\n      saveAndRender();\n    };\n\n    const delBtn = document.createElement('button');\n    delBtn.className = 'delete-btn';\n    delBtn.textContent = '✕';\n    delBtn.onclick = () => {\n      tasks = tasks.filter(t => t.id !== task.id);\n      saveAndRender();\n    };\n\n    li.appendChild(span);\n    li.appendChild(delBtn);\n    taskList.appendChild(li);\n  });\n\n  taskCount.textContent = `${tasks.length} task${tasks.length === 1 ? '' : 's'}`;\n}\n\n// 3. Event Listeners\nform.addEventListener('submit', (e) => {\n  e.preventDefault();\n  const text = input.value.trim();\n  if (!text) return;\n\n  tasks.push({\n    id: Date.now(),\n    text,\n    completed: false\n  });\n\n  input.value = '';\n  saveAndRender();\n});\n\nclearAllBtn.addEventListener('click', () => {\n  tasks = [];\n  saveAndRender();\n});\n\n// Initial render\nsaveAndRender();\nconsole.log('To-Do List application loaded successfully!');"
