      "style.css": ":root {\n  --bg-color: #020617;\n  --card-bg: #0f172a;\n  --text-color: #f8fafc;\n  --border-color: #1e293b;\n  --primary: #10b981;\n}\n\nbody.light-theme {\n  --bg-color: #f8fafc;\n  --card-bg: #ffffff;\n  --text-color: #0f172a;\n  --border-color: #e2e8f0;\n  --primary: #059669;\n}\n\nbody {\n  font-family: system-ui, sans-serif;\n  background: var(--bg-color);\n  color: var(--text-color);\n  margin: 0;\n  padding: 24px;\n  transition: background 0.3s, color 0.3s;\n}\n\n.dashboard { max-width: 760px; margin: 0 auto; }\n.dash-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; }\nh1 { margin: 0; font-size: 22px; color: var(--primary); }\n.tagline { margin: 4px 0 0; font-size: 12px; color: #94a3b8; }\n\n.btn-theme {\n  background: var(--card-bg);\n  color: var(--text-color);\n  border: 1px solid var(--border-color);\n  padding: 8px 14px;\n  border-radius: 8px;\n  cursor: pointer;\n  font-weight: bold;\n}\n\n.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 24px; }\n.stat-card {\n  background: var(--card-bg);\n  border: 1px solid var(--border-color);\n  padding: 16px;\n  border-radius: 12px;\n  text-align: center;\n}\n\n.s-lbl { font-size: 11px; color: #64748b; text-transform: uppercase; font-weight: bold; }\n.stat-card h2 { margin: 8px 0 0; font-size: 22px; color: var(--primary); }\n\n.notes-section {\n  background: var(--card-bg);\n  border: 1px solid var(--border-color);\n  padding: 20px;\n  border-radius: 14px;\n}\n\n.notes-section h3 { margin: 0 0 12px; font-size: 15px; }\n\ntextarea {\n  width: 100%;\n  box-sizing: border-box;\n  height: 120px;\n  background: var(--bg-color);\n  border: 1px solid var(--border-color);\n  color: var(--text-color);\n  padding: 12px;\n  border-radius: 8px;\n  font-family: inherit;\n  font-size: 13px;\n  outline: none;\n  resize: vertical;\n}\n\n.notes-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 10px; font-size: 11px; color: #64748b; }\n.btn-sm { background: #ef4444; color: white; border: none; padding: 4px 10px; border-radius: 6px; cursor: pointer; font-size: 11px; }",
      "script.js": "const notesArea = document.getElementById('notesArea');\nconst saveStatus = document.getElementById('saveStatus');\nconst clearNotesBtn = document.getElementById('clearNotesBtn');\nconst themeToggle = document.getElementById('themeToggle');\n\n// Load Notes\nnotesArea.value = localStorage.getItem('fahmrise_notes') || '';\n\nnotesArea.addEventListener('input', () => {\n  localStorage.setItem('fahmrise_notes', notesArea.value);\n  saveStatus.textContent = 'Saved at ' + new Date().toLocaleTimeString();\n});\n\nclearNotesBtn.addEventListener('click', () => {\n  notesArea.value = '';\n  localStorage.removeItem('fahmrise_notes');\n  saveStatus.textContent = 'Notes cleared';\n});\n\n// Theme Toggle\nlet isDark = true;\nthemeToggle.addEventListener('click', () => {\n  isDark = !isDark;\n  document.body.classList.toggle('light-theme', !isDark);\n});\n\nconsole.log('Dashboard initialized!');"
